'use strict';
/**
 * Seed data.
 *  seedMinimal – a clean business with one owner account (for real deployments).
 *  seedDemo    – "Greenfield Supermarket", Lagos: 3 locations, 4 registers, staff in every role,
 *                ~55 products, customers, and ~10 days of trading history generated by driving the
 *                real services (sessions, sales, payments, refunds, settlements, payouts, reconciliation),
 *                so every figure in the demo is internally consistent.
 */
const { newId, nowIso, setClock } = require('../lib/ids');
const { hashSecret, randomToken } = require('../lib/crypto');
const { ROLE_TEMPLATES, PERMISSIONS } = require('../services/permissions');
const { localDate, localMidnightUtc, addDays } = require('../lib/time');

function ean13(body12) {
  const d = body12.split('').map(Number);
  const sum = d.reduce((a, x, i) => a + x * (i % 2 ? 3 : 1), 0);
  return body12 + ((10 - (sum % 10)) % 10);
}

function baseBusiness(app, { name, currency = 'NGN', timezone = 'Africa/Lagos', locale = 'en-NG' }) {
  const { db } = app;
  const now = nowIso();
  const bid = newId('biz');
  db.run(`INSERT INTO businesses (id,name,currency,currency_minor,locale,timezone,prices_include_tax,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?)`, bid, name, currency, 2, locale, timezone, 1, now, now);
  for (const [code, cat, desc] of PERMISSIONS) db.run('INSERT OR IGNORE INTO permissions (code, category, description) VALUES (?,?,?)', code, cat, desc);
  const roles = {};
  for (const t of ROLE_TEMPLATES) {
    const id = newId('rol');
    db.run('INSERT INTO roles (id,business_id,code,name,description,max_discount_pct,is_system,created_at) VALUES (?,?,?,?,?,?,?,?)', id, bid, t.code, t.name, t.description, t.max_discount_pct, 1, now);
    for (const p of t.permissions) db.run('INSERT INTO role_permissions (role_id, permission_code) VALUES (?,?)', id, p);
    roles[t.code] = id;
  }
  return { bid, roles };
}

function addUser(app, bid, { username, full_name, role, password, pin, location, email, phone, mustChange = 0 }) {
  const id = newId('usr'); const now = nowIso();
  app.db.run(`INSERT INTO users (id,business_id,username,full_name,email,phone,password_hash,pin_hash,role_id,home_location_id,is_active,must_change_password,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
    id, bid, username, full_name, email || null, phone || null, hashSecret(password), pin ? hashSecret(pin) : null, role, location || null, 1, mustChange, now, now);
  return id;
}

function addPaymentMethod(app, bid, m, sort) {
  app.db.run(`INSERT INTO payment_methods (id,business_id,code,name,type,provider_code,is_active,allow_offline,allow_change,requires_reference,sort_order,shortcut,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`,
    newId('pmt'), bid, m.code, m.name, m.type, m.provider, 1, m.offline ? 1 : 0, m.type === 'cash' ? 1 : 0, m.provider === 'manual' ? 1 : 0, sort, m.shortcut || null, nowIso());
}

function seedMinimal(app) {
  const { db } = app;
  db.tx(() => {
    const { bid, roles } = baseBusiness(app, { name: 'My Business' });
    const loc = newId('loc');
    db.run('INSERT INTO locations (id,business_id,code,name,type,created_at) VALUES (?,?,?,?,?,?)', loc, bid, 'MAIN', 'Main store', 'store', nowIso());
    db.run('INSERT INTO registers (id,location_id,code,name,created_at) VALUES (?,?,?,?,?)', newId('reg'), loc, 'R01', 'Register 1', nowIso());
    db.run('INSERT INTO tax_rates (id,business_id,code,name,rate_bp,created_at) VALUES (?,?,?,?,?,?)', newId('tax'), bid, 'STD', 'Standard', 0, nowIso());
    addPaymentMethod(app, bid, { code: 'cash', name: 'Cash', type: 'cash', provider: 'cash', offline: true, shortcut: 'F8' }, 1);
    const pw = process.env.POS_OWNER_PASSWORD || `Setup${randomToken(4).replace(/[^A-Za-z0-9]/g, '')}9`;
    addUser(app, bid, { username: 'owner', full_name: 'Business Owner', role: roles.owner, password: pw, location: loc, mustChange: 1 });
    app.log('info', `Initial owner account: username "owner", password "${pw}" (must be changed at first sign-in)`);
  });
}

